#!/usr/bin/env bash
#
# id_stability: surviving solid:N ids do NOT shift after a mutating op.
#
# TopExp_Explorer order of *remaining* solids is the load-bearing
# invariant for the engine's decision-log / replay matcher. This test
# asserts that after suppressing solid:3 (in a multi-solid fixture),
# the volumes recorded for solid:1, solid:2, solid:4, ... still match
# the volumes they had before the suppression.

set -u

exe="$1"
fixtures="$2"
outdir="$3"

mkdir -p "$outdir"

fail() {
    echo "id_stability_smoke: $*" >&2
    exit 1
}

# A multi-solid compound generated by cad2csg_generate_fixtures. Four
# unit boxes along X with distinct volumes (1.0, 1.1, 1.2, 1.3) so the
# per-solid identity can be checked by both id and volume.
step="$fixtures/four_solids.step"
if [ ! -f "$step" ]; then
    echo "id_stability_smoke: SKIP (fixture missing: $step --"
    echo "  build cad2csg_generate_fixtures and run it to populate fixtures/)"
    exit 0
fi

baseline="$outdir/baseline.json"
"$exe" inspect "$step" --report "$baseline" >/dev/null 2>"$outdir/baseline.err" \
    || true  # inspect may exit nonzero on non-emit-ready models; that's fine.
[ -s "$baseline" ] || fail "baseline report not written"

# Suppress solid:3 via remove-solid, then re-analyze and compare volumes
# of every surviving solid.
mutated_i="$outdir/mutated.i"
mutated="$outdir/mutated.json"
"$exe" simplify "$step" --remove-solid solid:3 \
    --out "$mutated_i" --report "$mutated" \
    >"$outdir/mutated.out" 2>"$outdir/mutated.err" || true
[ -s "$mutated" ] || fail "mutated report not written"

python3 - "$baseline" "$mutated" <<'PY'
import json
import sys

with open(sys.argv[1], "r", encoding="utf-8") as h:
    base = json.load(h)
with open(sys.argv[2], "r", encoding="utf-8") as h:
    mut = json.load(h)

# Index solids by id; baseline must include solid:3, mutated must not
# (it was suppressed).
base_by_id = {s["id"]: s for s in base["solids"]}
mut_by_id  = {s["id"]: s for s in mut["solids"]}

if "solid:3" not in base_by_id:
    print(f"baseline missing solid:3 (fixture too small?)", file=sys.stderr)
    sys.exit(2)

if "solid:3" in mut_by_id:
    print(f"solid:3 still present after --remove-solid solid:3", file=sys.stderr)
    sys.exit(1)

# Every surviving id in baseline (except solid:3) must reappear in mutated
# with the same volume. We compare to 1e-9 relative tolerance.
shifted = []
for sid, b in base_by_id.items():
    if sid == "solid:3":
        continue
    m = mut_by_id.get(sid)
    if m is None:
        shifted.append((sid, "missing"))
        continue
    vb = b.get("volume", 0.0)
    vm = m.get("volume", 0.0)
    if abs(vb - vm) > max(1e-9 * abs(vb), 1e-12):
        shifted.append((sid, f"volume changed: {vb} -> {vm}"))

if shifted:
    print("id stability violated — surviving solid:N ids shifted or changed:",
          file=sys.stderr)
    for sid, why in shifted:
        print(f"  {sid}: {why}", file=sys.stderr)
    sys.exit(1)

print(f"id_stability_smoke: OK ({len(base_by_id) - 1} surviving solids stable)")
PY

exit 0
